{"command": "find $WORKSPACE_DIR/documents/matters -maxdepth 3 -type f -name "*.docx" | head -20 | while read f; do echo "=== $f ==="; python3 -c "
import sys
try:
    from docx import Document
    doc = Document('$f')
    for p in doc.paragraphs:
        if 'antitrust' in p.text.lower() or 'second.request' in p.text.lower() or 'clearance' in p.text.lower():
            print(f'  PARA: {p.text[:200]}')
except Exception as e:
    print(f'  ERROR: {e}')
" 2>/dev/null; done"}

